			/**
			 * 목록화면에서 전달받은 정보구성
			 ** @param {"CREATE" | "READ"} psType 게시글 상세 조회 타입
			 * @param {any} poData 데이터
			 */
			function setDtlData(psType, poData) {
			    
			    var dsBoardList = app.lookup("dsBoardList");
			    var dsDtlReply = app.lookup("dsDtlReply");
			    var dmDtlParam = app.lookup("dmDtlParam");
			    
			    var vcGrpBoard = app.lookup("grpBoardDtl");
			    var vcGrpBoardLayout = vcGrpBoard.getLayout();
			    
			    var vcBoardTitle = app.lookup("comFormTitle");
			    var vcListBtn = app.lookup("btnList");
			    
			    if (psType != "CREATE" && !poData.BBSCTT_ESNTAL_NO) {
			        util.Msg.alert(app, "데이터가 존재하지 않습니다. 관리자에게 문의하세요.", null, function() {
			            
			            // 목록 페이지로 이동
			            vcListBtn.click();
			        }, "안내");
			    } else {
			        dmDtlParam.build(poData);
			    
			        // 1. 게시글유형구분코드 별로 고유 Row Visible 처리
			        var vaBbscttType = dmDtlParam.getValue("BBSCTT_TYPE_SE_CD");
			        var vcCrisisLabelOutput = app.lookup("optCrisisMngSeCd2");
			        var vcCrisisGroup = app.lookup("grpCrisisMng");
			        var vcClienaGradeGroup = app.lookup("grpClienaGrade");
			    
			        if (vaBbscttType == '31') {
			            vcBoardTitle.title = "네이버"
			            vcGrpBoardLayout.setRowVisible(1, true);
			            vcGrpBoardLayout.setRowVisible(8, false);
			            
			            vcGrpBoard.replaceConstraint(vcClienaGradeGroup, {
			                "rowIndex" : 4,
			                "colIndex" : 3,
			                "colSpan" : 3
			            });
			            vcGrpBoard.replaceConstraint(vcCrisisLabelOutput, {
			                "rowIndex" : 4,
			                "colIndex" : 6
			            });
			            vcGrpBoard.replaceConstraint(vcCrisisGroup, {
			                "rowIndex" : 4,
			                "colIndex" : 7
			            });
			        } else {
			            vcGrpBoardLayout.setRowVisible(1, false);
			            vcGrpBoardLayout.setRowVisible(8, true);
			            
			            vcGrpBoard.replaceConstraint(vcClienaGradeGroup, {
			                "rowIndex" : 4,
			                "colIndex" : 3,
			                "colSpan" : 5
			            });
			            vcGrpBoard.replaceConstraint(vcCrisisLabelOutput, {
			                "rowIndex" : 3,
			                "colIndex" : 4
			            });
			            vcGrpBoard.replaceConstraint(vcCrisisGroup, {
			                "rowIndex" : 3,
			                "colIndex" : 5
			            });
			        }
			        
			        if (vaBbscttType == '18') {
			            vcBoardTitle.title = "카카오톡 오픈채팅"
			            vcGrpBoardLayout.setRowMinHeight(2, 455);
			            vcGrpBoardLayout.setRowVisible(3, true);
			        } else {
			            vcGrpBoardLayout.setRowMinHeight(2, 430);
			            vcGrpBoardLayout.setRowVisible(3, false);
			        }
			        
			        if (vaBbscttType == '36') {
			            vcBoardTitle.title = "구글"
			        }
			        
			        // CRUD에 따른 화면 구성 함수
			        setDtlCrud(psType);
			        
			        util.Submit.send(app, "subOnload", function(pbSuccess) {
			            if (pbSuccess) {
			                if (psType == "CREATE") {
			                    dsBoardList.clear();
			                    dsDtlReply.clear();
			                    util.Control.reset(app, "cmnHtmlEditor");
			                    
			                    if (vaBbscttType != '31') {
			                        vcGrpBoardLayout.setRowVisible(8, false);
			                    }
			                
			                    dsBoardList.insertRowData(0, true, poData);
			                    
			                    dsBoardList.setValue(0, "WRTR_NM_ENCPT", voUserNm);
			                    dsBoardList.setValue(0, "WRTR_ID", voUserId);
			                    
			                    console.log("dsBoardList ::: " + dsBoardList.getRowData(0).BBSCTT_TYPE_SE_CD);
			                    
			                    util.Control.redraw(app, "grpBoardDtl");
			                } else {
			                    doDtlList();
			                }
			            
			            }
			        });
			    }
			}
			exports.setDtlData = setDtlData;

			/**
			 * CRUD 권한에 따른 화면 구성
			 ** @param {"CREATE" | "READ" | "UPDATE"} psType 게시글 상세 조회 타입
			 */
			function setDtlCrud(psType) {
			    var vcGrpCont       = app.lookup("grpCont");
			    var vcGrpCont2      = app.lookup("grpCont2");
			    var vcGrpHpgeUrl    = app.lookup("grpHpgeUrl");
			    var vcEditer        = app.lookup("cmnHtmlEditor");
			    var voDmDtlParma    = app.lookup("dmDtlParam");
			    var vaBbscttType    = voDmDtlParma.getValue("BBSCTT_TYPE_SE_CD");
			//    util.Control.setReadOnly(app, true, "grpBoardDtl");

			    /*
			     * 1. 원글 내용 및 답글 내용 Control Visible 처리
			     * 2. 각 Control readOnly&Enabled 처리
			     * 3. Button Visible 처리
			     */
			    
			    msBrdDtlType = psType;
			    
			    if (psType == "READ") {
			        
			        if(vaBbscttType == "31") {
			            
			            // grpHpgeUrl setColumnVisible 처리
			            vcGrpHpgeUrl.getLayout().setColumnVisible(0, false);
			            vcGrpHpgeUrl.getLayout().setColumnVisible(1, true);
			        }
			        
			        // editor 숨김처리 및 html 스니펫 출력
			        vcGrpCont.getLayout().setRowVisible(0, true);
			        vcGrpCont.getLayout().setRowVisible(1, false);
			        
			        // editor 숨김처리 및 html 스니펫 출력
			        vcGrpCont2.getLayout().setRowVisible(0, true);
			        vcGrpCont2.getLayout().setRowVisible(1, false);
			        
			        // 원글 Control 통제
			        util.Control.setEnable(app, true, ["grpCnsltntAsgn", "grpCrisisMng", "grpReteDlivCmptn"]);      // 상담원할당, 위기관리구분, 답글전달 완료
			        util.Control.setEnable(app, false, ["rdbSxdc", "cbgYngbgsStts", "grpLinkPrcs"]);                // 내담자 성별, 상담대상구분, 연계처리내역
			        util.Control.setEnable(app, false, ["cmbAcbg", "cmbGrade", "cmbGrdtn"]);                        // 내담자 학력
			        util.Control.setEnable(app, false, ["cmbPetbc", "ipbPetbcCn"]);                                 // 피상담자구분
			        util.Control.setEnable(app, false, ["cmb14", "cmb15", "cmb16", "cmb17"]);                       // 문제상태
			        util.Control.setReadOnly(app, true, ["ipbTitle2", "grpProbmStts"]);                             // 제목, 문제영역
			        
			        // 우측 하단(CRUD 버튼) Button 통제 - 수정,삭제 : true / 저장,취소 : false
			        util.Control.setVisible(app, true, ["btnRevise", "btnDelete"]);
			        util.Control.setVisible(app, false, ["btnSave", "btnRestore"]);
			        
			        // 연계상담에서 온경우 버튼 숨김
			        if (bbscrsYN == "Y") {
			            util.Control.setVisible(app, false, ["btn4", "btnSave", "btnRevise", "btnRestore", "btnDelete", "btnList"]);
			        }
			        
			    } else {
			        var dsBoardList = app.lookup("dsBoardList");
			        var dsDtlReply = app.lookup("dsDtlReply");
			        
			        if(vaBbscttType == "31") {
			            
			            // grpHpgeUrl setColumnVisible 처리
			            vcGrpHpgeUrl.getLayout().setColumnVisible(0, true);
			            vcGrpHpgeUrl.getLayout().setColumnVisible(1, false);
			        }
			        
			        // 원글(AYE100) HtmlSnippet&HtmlEditor Visible 처리
			        vcGrpCont.getLayout().setRowVisible(0, false);
			        vcGrpCont.getLayout().setRowVisible(1, true);
			        
			        // 원글 Control 통제
			        util.Control.setEnable(app, false, ["grpCnsltntAsgn", "grpCrisisMng", "grpReteDlivCmptn"]);
			        util.Control.setEnable(app, true, ["rdbSxdc", "cmbAcbg", "cmbPetbc", "cbgYngbgsStts", "grpLinkPrcs"]);
			        util.Control.setReadOnly(app, false, ["ipbTitle2", "grpProbmStts"]);
			        
			        // 우측 하단(CRUD 버튼) Button 통제 - 수정,삭제 : false / 저장,취소 : true
			        util.Control.setVisible(app, false, ["btnRevise", "btnDelete"]);
			        util.Control.setVisible(app, true, ["btnSave", "btnRestore"]);
			        
			        if (psType == "UPDATE") {
			            
			            // 게시글유형구분코드 != '31' and 답글 데이터 존재 안할때 ▷ 데이터셋 Insert
			            if(vaBbscttType != "31") {
			                // 답글(AYE120) HtmlSnippet&텍스트에리어 Visible 처리
			                vcGrpCont2.getLayout().setRowVisible(0, false);
			                vcGrpCont2.getLayout().setRowVisible(1, true);
			                
			                console.log("dsDtlReply.getRowCount() ::: " + dsDtlReply.getRowCount());
			                
			                if (dsDtlReply.getRowCount() == 0) {
			                    dsDtlReply.insertRow(0);
			                    
			                    dsDtlReply.setValue(0, "BBSCTT_ESNTAL_NO", dsBoardList.getValue(0, "BBSCTT_ESNTAL_NO"))
			                    dsDtlReply.setValue(0, "BBSCTT_TYPE_SE_CD", dsBoardList.getValue(0, "BBSCTT_TYPE_SE_CD"))
			                }
			            }
			            
			            // 렌더링 완료 후 동작(에디터 load 이후)
			            cpr.core.DeferredUpdateManager.INSTANCE.asyncExec(function() {
			                vcEditer.setValue(dsBoardList.getValue(0, "BBSCTT_CN"), false);                  
			            });
			            
			            // 내담자 학력 Enabled 처리
			            if (dsBoardList.getValue(0, "ACBG_SE_CD") != "") {
			                cmbAcbgSelectionChange("UPDATE");
			                cmbGradeSelectionChange("UPDATE");
			            }
			            
			            // 피상담자구분 Enabled 처리
			            if (dsBoardList.getValue(0, "REAL_CONSTT_SE_CD") != "") {
			                cmbPetbcSelectionChange("UPDATE");
			            }
			            
			            // 문제상태 Enabled 처리
			            if (dsBoardList.getValue(0, "PROBM_STTS_LCLAS_SE_CD") != "") {
			                cmbProbmSttsLclasSelectionChange("UPDATE");
			                cmbProbmSttsMlsfcSelectionChange("UPDATE");
			                cmbProbmSttsSclasSelectionChange("UPDATE");
			                cmbProbmCasLclasSelectionChange("UPDATE");
			                cmbProbmCasSclasSelectionChange("UPDATE");
			            }
			            
			        } else if (psType == "CREATE") {
			            
			            cpr.core.DeferredUpdateManager.INSTANCE.asyncExec(function() {
			                vcEditer.setValue("", false);
			            });
			            
			            util.Control.setVisible(app, false, ["btnRestore"]);

			        }
			    }
			}

			/**
			 * 목록창 전환
			 */
			function selectMdiListItem() {
			    var hostApp = app.getHostAppInstance();
			    
			    if (hostApp.hasAppMethod("selectMdiItem")) {
			        hostApp.callAppMethod("selectMdiItem", 1);
			    }
			    
			    // 컨테이너에 스크롤이 포함된경우 최상단으로 변경
			    app.getContainer().scrollTo(0, 0);
			}

