			function onBodyLoad3(e){
			    
			    console.log("연계상담게시판 voInitValue ::: " + app.getHostProperty("initValue"));
			    
			    if (app.getHostProperty("initValue") != null && app.getHostProperty("initValue") != "") {
			        bbscrsYN = "Y";
			        
			        var voInitValue = app.getHostProperty("initValue");
			        console.log("initValue : ", voInitValue);
			        var voInitValue = app.getHostProperty("initValue");
			        var dmDtlParam = app.lookup("dmDtlParam"); 
			        
			        if(voInitValue["type"] == "bbscrs") {
			            dmDtlParam.setValue("BBSCTT_ESNTAL_NO", voInitValue["bbscttEsntalNo"]);
			            dmDtlParam.setValue("BBSCTT_TYPE_SE_CD", voInitValue["bbscttTypeSeCd"]);
			            dmDtlParam.setValue("NUM", 1);
			            
			            doDtlList();
			            
			            util.Control.setVisible(app, false, ["btn4", "btnSave", "btnRevise", "btnRestore", "btnDelete"]);
			                
			        }
			    }   
			}

