			/*
			 * 인풋 박스에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onIpbHpgeUrlClick(e){
			    var ipbHpgeUrl = e.control;
			    
			    var voDsBrdDtlList  = app.lookup("dsBoardList");
			    var linkUrl         = voDsBrdDtlList.getValue(0, "HPGE_URL_ADDR");
			    
			    if (ipbHpgeUrl.readOnly) {
			        if (linkUrl != null && linkUrl != "") {
			            window.open(linkUrl, "CafeOpen", "target='_blank'");
			        }
			    }
			}

			/*
			 * 아웃풋(optHpgeUrl)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
