			/*
			 * "저장" 버튼(btnSave)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnSaveClick(e) {
			    var btnSave = e.control;
			    
			    /*
			     * validation Check
			     * 1. 게시글 제목 - AYE100 ok
			     * 2. 게시글 내용 - AYE100 ok  
			     * 3. 내담자 성별 - AYE100 ok
			     */
			    
			    var _isModified = false;
			    
			    var dsBoardList = app.lookup("dsBoardList");
			    var dsDtlReply = app.lookup("dsDtlReply");
			    var vcBoardTitle = app.lookup("ipbTitle2");
			    var vcEditer = app.lookup("cmnHtmlEditor");
			    
			    var vcboardTitleVal = vcBoardTitle.value;
			    
			    var preContent = dsBoardList.getValue(0, "BBSCTT_CN");
			    var nextContent = vcEditer.getValue();
			    
			    console.log("nextContent ::: " + nextContent);
			    console.log("nextContent.length ::: " + nextContent.length);
			    
			    // 답글 내용 최초 작성시 공백 제거
			    var removeGapContent = "";
			    var splitReplyContent = nextContent.split("&nbsp;");
			    splitReplyContent.some(function(each){
			        if (each.trim().length > 0) {
			            removeGapContent += each;
			        }
			    });
			    
			    if (!util.validate(app, "ipbTitle2")) {
			        return false;
			    } else {
			        if (vcboardTitleVal.trim().length == 0) {
			            util.Msg.alert(app, "WRN-M001", "답글 제목", function() {
			                vcBoardTitle.focus();
			            }, "알림");
			            return false;
			        }
			    }
			    if (removeGapContent.length == 0) {
			        util.Msg.alert(app, "WRN-M001", "답글 내용", null, "알림");
			        return false;
			    } else {
			        if (nextContent != preContent) {
			            console.log("답글 변경한다~~~");
			            dsBoardList.setValue(0, "BBSCTT_CN", nextContent);
			        }
			    }
			    if (!util.validate(app, "rdbSxdc")) return false;
			    
			    console.log("게시글(원글) 변경사항 Check ::: " + dsBoardList.isModified());
			    console.log("답글 변경사항 Check ::: " + dsDtlReply.isModified());
			    
			    /*
			     * 2023.04.14 : 작성
			     * 공통적인 validation Check 후
			     * 수정 페이지 ▷ 데이터셋 변경유무 확인
			     * 등록 페이지 ▷ Pass
			     * 이외 ▷ alert 호출
			     * 2023.04.19 : 필요없다고 판단됨
			     */
			    if (msBrdDtlType == "UPDATE") {
			        if (dsBoardList.isModified() || dsDtlReply.isModified()) {
			            _isModified = true;
			        }
			    } else if (msBrdDtlType == "CREATE") {
			        _isModified = true;
			    } else {
			        util.Msg.alert(app, "잘못된 접근입니다.");
			        return false;
			    }
			    
			    if (_isModified){
			    	util.Msg.confirm(app, "CRM-M001", null, function() {
			    	    util.Submit.send(app, "subDtlSave", function(pbSuccess) {
			    	        if (msBrdDtlType == "CREATE") {
			    	            var dmDtlParam = app.lookup("dmDtlParam");
			    	            
			    	            // 저장시 재조회를 위한 게시글 시퀀스값 저장
			                    var subDtlSave = app.lookup("subDtlSave");         
			                    var vaBbscttNo = subDtlSave.getMetadata("BBSCTT_ESNTAL_NO");
			                    var vaBbscttType = subDtlSave.getMetadata("BBSCTT_TYPE_SE_CD");
			                    
			                    dmDtlParam.setValue("BBSCTT_ESNTAL_NO", vaBbscttNo);
			                    dmDtlParam.setValue("BBSCTT_TYPE_SE_CD", vaBbscttType);
			    	        }
			    	        
			                // CRUD에 따른 화면 구성 함수
			                setDtlCrud("READ");
			                
			                // 게시글(원글) 및 답글 재조회
			                doDtlList("save");
			            });
			    	}, null, "안내");
			    } else {
			        util.Msg.alert(app, "INF-M006");
			    }
			}

