			function onBtnDeleteClick(e) {
			    var btnDelete = e.control;
			    
			    var dsBoardList = app.lookup("dsBoardList");
			    var dsDtlReply = app.lookup("dsDtlReply");
			    
			    var userGroupAuthrt = user["GROUP_AUTHRT_SE_CD"];               // session 그룹권한구분코드 
			    var loginId = util.Auth.getUserInfo(app, "USER_ID");            // session ID
			    var boardFrstRegId = dsBoardList.getValue(0, "WRTR_ID");        // 원글(AYE100) 최초 작성자 ID
			    var replyFrstRegId = dsDtlReply.getValue(0, "FRST_RGTR_ID");    // 답글(AYE120) 최초 작성자 ID
			    
			    console.log("userGroupAuthrt != 340 ::: " + (userGroupAuthrt != "340"));
			    console.log("boardFrstRegId == loginId ::: " + (boardFrstRegId == loginId));
			    console.log("replyFrstRegId == loginId ::: " + (replyFrstRegId == loginId));
			    
			    // 삭제 권한 ▷ 관리자(그룹권한구분코드 340 이외의 전부 해당)이거나 게시글 작성 또는 답글 작성자인 경우
			    if(userGroupAuthrt != "340" || boardFrstRegId == loginId || replyFrstRegId == loginId) {
			        util.Msg.confirm(app, "CRM-M002", null, function() {
			            
			            // 원글(AYE100) 데이터 삭제
			            dsBoardList.deleteRow(0);
			            
			            // 답글(AYE120) 데이터 삭제
			            if (dsDtlReply.getRowCount() != 0) {
			                dsDtlReply.deleteRow(0);
			            }
			            
			            // 서브미션 호출
			            util.Submit.send(app, "subDtlSave", function(pbSuccess) {
			                if (pbSuccess) {
			                    // 목록창 전환
			                    selectMdiListItem();
			                }
			            });
			        });
			    } else{
			        util.Msg.alert(app, "삭제 권한이 없는 사용자 입니다.");
			    }
			}

